package com.fasterxml.jackson.core.json.async;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.async.ByteArrayFeeder;
import com.fasterxml.jackson.core.async.NonBlockingInputFeeder;
import com.fasterxml.jackson.core.io.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.ByteQuadsCanonicalizer;
import com.fasterxml.jackson.core.util.VersionUtil;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for NonBlockingJsonParser.feedInput
 */
public class NonBlockingJsonParser_feedInput_TriageGen0Test {

    private NonBlockingJsonParser parser;
    private IOContext ioContext;
    private ByteQuadsCanonicalizer sym;

    @Before
    public void setUp() {
        ioContext = new IOContext();
        sym = ByteQuadsCanonicalizer.newInstance(null);
        parser = new NonBlockingJsonParser(ioContext, 0, sym);
    }

    /**
     * Helper to set private fields via reflection for state manipulation
     */
    private void setField(String name, Object value) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(parser, value);
    }

    /**
     * Helper to get private fields via reflection
     */
    private Object getField(String name) throws Exception {
        Field field = NonBlockingJsonParser.class.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(parser);
    }

    @Test
    public void testFeedInput_Success() throws Exception {
        // Initial State
        setField("_inputPtr", 0);
        setField("_inputEnd", 0);
        setField("_endOfInput", false);
        setField("_currInputProcessed", 0);
        setField("_origBufferLen", 0);
        setField("_currInputRowStart", 0);

        byte[] buf = new byte[]{'{', '}'};
        int start = 0;
        int end = 2;

        parser.feedInput(buf, start, end);

        assertEquals(buf, getField("_inputBuffer"));
        assertEquals(start, getField("_inputPtr"));
        assertEquals(end, getField("_inputEnd"));
        assertEquals(2, getField("_origBufferLen"));
        assertEquals(0, getField("_currInputProcessed"));
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_RemainingInput() throws Exception {
        // Simulate remaining input: _inputPtr < _inputEnd
        setField("_inputPtr", 0);
        setField("_inputEnd", 5);

        byte[] buf = new byte[]{1, 2, 3};
        parser.feedInput(buf, 0, 3);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_EndBeforeStart() throws Exception {
        setField("_inputPtr", 0);
        setField("_inputEnd", 0);
        setField("_endOfInput", false);

        byte[] buf = new byte[]{1, 2, 3};
        // end < start
        parser.feedInput(buf, 2, 1);
    }

    @Test(expected = RuntimeException.class)
    public void testFeedInput_Error_AlreadyClosed() throws Exception {
        setField("_inputPtr", 0);
        setField("_inputEnd", 0);
        setField("_endOfInput", true);

        byte[] buf = new byte[]{1};
        parser.feedInput(buf, 0, 1);
    }

    @Test
    public void testFeedInput_UpdatePointersAndRowStart() throws Exception {
        // Setup state simulating a previous buffer
        setField("_inputPtr", 0);
        setField("_inputEnd", 0);
        setField("_endOfInput", false);
        setField("_currInputProcessed", 10);
        setField("_origBufferLen", 10);
        setField("_currInputRowStart", 5); // Row started at index 5 of the 10-byte buffer

        byte[] buf = new byte[]{1, 2, 3, 4, 5};
        int start = 0;
        int end = 5;

        // Calculation expected:
        // _currInputProcessed = 10 + 10 = 20
        // _currInputRowStart = 0 - (0 - 5) = 5

        parser.feedInput(buf, start, end);

        assertEquals(20, (int) getField("_currInputProcessed"));
        assertEquals(5, (int) getField("_currInputRowStart"));
        assertEquals(5, (int) getField("_origBufferLen"));
    }

    @Test
    public void testFeedInput_UpdatePointersAndRowStart_Offset() throws Exception {
        // Setup state where row start is relative to the end of the buffer
        setField("_inputPtr", 0);
        setField("_inputEnd", 0);
        setField("_endOfInput", false);
        setField("_currInputProcessed", 100);
        setField("_origBufferLen", 10);
        setField("_currInputRowStart", 95); 

        byte[] buf = new byte[]{1, 2, 3};
        int start = 2;
        int end = 5;

        // Calculation expected:
        // _currInputProcessed = 100 + 10 = 110
        // _currInputRowStart = 2 - (0 - 95) = 2 - (-95) = 97

        parser.feedInput(buf, start, end);

        assertEquals(110, (int) getField("_currInputProcessed"));
        assertEquals(97, (int) getField("_currInputRowStart"));
    }
}
